/* Scoped adapter around the retained details study. No native state or Reddit actions. */
(function(){
'use strict';
if(new URLSearchParams(location.search).get('adaptive-reader')!=='1'||parent===window)return;
const style=document.createElement('style');style.textContent='html,body{height:100%;margin:0;overflow:hidden!important}body>.workbench,body>.rationale,.study-head,.detail-notes,.measurement,.shared-shell-nav{display:none!important}.details-workspace,.details-workspace>.study{display:block!important;width:100%!important;max-width:none!important;height:100%!important;margin:0!important;padding:0!important}.detail-phone,.phone.detail-phone{width:100%!important;max-width:none!important;height:100dvh!important;min-height:0!important;border:0!important;border-radius:0!important;box-shadow:none!important;padding-bottom:0!important}.detail-phone>.statusbar{display:none!important}.detail-scroll:focus-visible{outline:3px solid var(--accent);outline-offset:-3px}.detail-phone .thread,.detail-phone .post-card{background:var(--card)!important}';document.head.append(style);
let themeConfig=null;
const send=data=>parent.postMessage(data,location.origin);
function themeReader(){const T=window.RelaxeStudyTheme,phone=D('#detail-phone');if(!themeConfig||!T||!phone)return;const tokens=T.tokens(T.directions[0],{foundation:'selected',appearance:themeConfig.appearance,palette:themeConfig.palette||'blue',text:themeConfig.text});for(const [key,value]of Object.entries(tokens))phone.style.setProperty(key,value);for(const [key,source]of [['--bg','--canvas'],['--divider','--outline'],['--muted','--secondary'],['--tint','--container']])phone.style.setProperty(key,tokens[source]);}
function fitFooter(){themeReader();window.RelaxeReaderAppearance?.syncPresentation();const phone=D('#detail-phone'),scroll=D('.detail-scroll'),footer=D('.detail-bottom');if(!phone||!scroll||!footer)return;const target=innerHeight<400||preferences.text>=2&&innerHeight<520?scroll:phone;if(footer.parentElement!==target)target.append(footer)}
new MutationObserver(fitFooter).observe(D('#detail-phone'),{childList:true,subtree:true});window.addEventListener('resize',fitFooter);fitFooter();
function busy(){return window.RelaxeReaderAppearance?.active||D('#detail-dialog').open||composerOpen||!!discussion().tool}
function back(){if(window.RelaxeReaderAppearance?.requestClose())return;if(D('#detail-dialog').open){D('#detail-dialog').close();return}if(composerOpen){composerOpen=false;notice='Draft kept locally.';renderDetails();return}if(discussion().tool){discussion().tool=null;renderDetails();return}document.querySelectorAll('video').forEach(v=>v.pause());send({type:'relaxe-adaptive-reader-close'})}
document.addEventListener('click',event=>{if(event.target.closest('[data-action="back"]')&&!busy()){event.preventDefault();event.stopImmediatePropagation();back()}},true);
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!busy()){event.preventDefault();event.stopImmediatePropagation();back()}},true);
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==parent)return;if(event.data?.type==='relaxe-adaptive-reader-focus'){const region=D('.detail-scroll');region.tabIndex=0;region.setAttribute('role','region');region.setAttribute('aria-label','Post and comments');region.focus({preventScroll:true});return}if(event.data?.type==='relaxe-adaptive-reader-suspend'){document.querySelectorAll('video').forEach(v=>v.pause());return}if(event.data?.type==='relaxe-adaptive-reader-back'){back();return}if(event.data?.type!=='relaxe-adaptive-reader-config')return;const v=event.data.values;if(!v||!['p1','p2','p3','p4','p5'].includes(v.post)||!['light','dark','amoled'].includes(v.appearance)||!['1','1.3','2'].includes(v.text)||!['guest','weekendreader'].includes(v.account)||v.palette!==undefined&&!['blue','rose','amber','stone'].includes(v.palette))return;themeConfig=v;if(preferences.post!==v.post){composerOpen=false;composerTarget=null;composerError='';sending=false;requestEpoch++}preferences.post=v.post;preferences.theme=v.appearance==='light'?'light':'dark';preferences.text=+v.text;preferences.width=600;preferences.state=v.account==='guest'?'guest':'ready';renderDetails();if(v.appearance==='amoled')D('#detail-phone').style.setProperty('--bg','#000');fitFooter();});
send({type:'relaxe-adaptive-reader-ready'});
})();
